    // Branch-coverage vectors for methods with several internal dispatch/fallback branches that the vectors above don't reach (each comment names the branch hit)

    @ParameterizedTest(name = "[{index}] method {0}: account {1}")
    @CsvSource(delimiter = '|', value = {
        "C5 | 0000900000 | false", // digits 1-4 all 0, digit 5 out of [1,8] range
        "C5 | 0500009000 | true",  // digit 1 == 0, digit 2 (1-8) in range, formula compared at index 6
        "C5 | 0500000000 | false", // same branch, formula mismatch
        "C5 | 1234567890 | false", // leading digit 1 -> delegates to M29 (invalid)
        "C5 | 9234567890 | true",  // leading digit 9 -> delegates to M29 (valid)
        "C5 | 3234567890 | false", // leading digit 3 -> delegates to M00 (invalid)
        "C5 | 2000000000 | false", // none of the special cases apply -> unconditional false
        "51 | 7914220587 | true",  // digit 3 != 9, sumA (Modulus 11, weights 7-2) valid
        "51 | 2684737828 | true",  // sumA invalid, sumB (Modulus 11, weights 6-2) valid
        "51 | 5168795486 | true",  // sumA/sumB invalid, sumC (Modulus 10) valid
        "51 | 2914177763 | true",  // sumA/sumB/sumC invalid, digit 10 < 7, Modulus-7 fallback valid
        "51 | 6634876475 | false", // same fallback, formula mismatch
        "51 | 0105244939 | false", // sumA/sumB/sumC invalid, digit 10 >= 7 -> rejected outright
        "B8 | 2735730177 | true",  // primary Modulus-11 formula valid
        "B8 | 1706859643 | true",  // primary formula invalid, M29 fallback valid
        "B8 | 4273675928 | false", // both invalid, outside the 'not checked' exception ranges
        "84 | 2806520667 | true",  // no Ausnahme, sumA (Modulus 11) valid
        "84 | 3607756696 | true",  // no Ausnahme, sumA invalid, sumB (Modulus 7) valid
        "84 | 9400189902 | true",  // no Ausnahme, sumA/sumB invalid, sumC (Modulus 10) valid
        "84 | 2100969422 | false", // no Ausnahme, all three formulas invalid
        "84 | 0898857649 | true",  // Ausnahme applies, first Modulus-11 variant matches
        "84 | 5791244665 | true",  // Ausnahme applies, first variant fails, second matches
        "96 | 1715391401 | true",  // valid via M19
        "96 | 1313337832 | true",  // M19 invalid, valid via M00
        "96 | 0041465264 | true",  // M19/M00 invalid, digit 1 == 0, value inside reserved range
        "96 | 0642729359 | false", // M19/M00 invalid, digit 1 == 0, value outside reserved range
        "96 | 1041465264 | false", // M19/M00 invalid, digit 1 != 0 -> always false
        "A8 | 2003798909 | true",  // digit 3 != 9, sumA (Modulus 11, weights 7-2) valid
        "A8 | 4809387549 | true",  // sumA invalid, sumB (Modulus 10) valid
        "A8 | 8001465264 | false", // sumA/sumB invalid
        "35 | 6187376609 | true",  // remainder in [1,9], normal comparison
        "35 | 8041465264 | false", // same branch, mismatch
        "35 | 2879069222 | true",  // remainder == 10 -> compares digit 9 to digit 10 instead
        "35 | 2091253128 | false", // same branch, digits differ
        "35 | 1739348370 | true",  // sum % 11 == 0 -> remainder 11 collapses to 0
        "86 | 4809387549 | true",  // own formula (Modulus 10) valid
        "86 | 4703625701 | true",  // own formula invalid, delegates to M33 (valid)
        "86 | 8001465264 | false", // own formula and M33 delegate both invalid
        "95 | 0041465264 | false", // digit 1 == 0 but outside every reserved range -> formula applies
        "57 | 5100000003 | true",  // 'first' selects the WEIGHTS_M57A formula, compared at index 9
        "57 | 5100000004 | false", // same branch, mismatch
        "57 | 3230000000 | true",  // 'first' selects the WEIGHTS_M57B formula, compared at index 2
        "57 | 3240000000 | false", // same branch, mismatch
    })
    void calculate_knownVectors_branchCoverage(String code, String account, boolean expectedValid) {
        assertVector(code, account, expectedValid);
    }

