    @Test
    void calculate_c5_leadingSevenOrEightException_delegatesToM09() {
        assertThat(GermanCheckDigitMethod.C5.calculate(BLZ, "7000000000".toCharArray()).isChecked()).isFalse();
        assertThat(GermanCheckDigitMethod.C5.calculate(BLZ, "8500000000".toCharArray()).isChecked()).isFalse();
    }

    @Test
    void calculate_b8_leading2Or3DigitsInExceptionRange_notChecked() {
        assertThat(GermanCheckDigitMethod.B8.calculate(BLZ, "5614443803".toCharArray()).isChecked()).isFalse();
    }

    @Test
    void calculate_m95_reservedRanges_allFiveVariants_notChecked() {
        assertThat(GermanCheckDigitMethod.M95.calculate(BLZ, "0013798909".toCharArray()).isChecked()).isFalse();
        assertThat(GermanCheckDigitMethod.M95.calculate(BLZ, "0409770020".toCharArray()).isChecked()).isFalse();
        assertThat(GermanCheckDigitMethod.M95.calculate(BLZ, "0715391401".toCharArray()).isChecked()).isFalse();
        assertThat(GermanCheckDigitMethod.M95.calculate(BLZ, "0969854394".toCharArray()).isChecked()).isFalse();
    }

    private static void assertVector(String code, String account, boolean expectedValid) {
        GermanCheckDigitMethod method = GermanCheckDigitMethod.fromCode(code);

        CheckDigitResult result = method.calculate(BLZ, account.toCharArray());

        assertThat(result.isChecked()).as("method %s should perform a real check for %s", code, account).isTrue();
        assertThat(result.isValid()).as("method %s, account %s", code, account).isEqualTo(expectedValid);
    }

